// 原撤职两头＋真实Common缓存对象绑定；格式和裁剪边界门不冒生命、控制或World资格验收。
#define POLITICAL_DISMISSAL_SOURCE_FIXTURE_ONLY
#include "political_dismissal_source_test.cpp"
#include "resident/domains/politics/dismissal_sources/political_dismissal_receipts.hpp"
#include "resident/kernel/command_types.hpp"
#include "resident/checkpoint/codec_visitor.hpp"
namespace {
bool exact(const CommitResult& r,const StableId& source,const StableId& office){const auto* e=r.details?std::get_if<PoliticsEffects>(&r.details->data):nullptr;return r.ok&&r.kind=="political_dismiss"&&e&&e->appointment_id.empty()&&e->fact_ids==std::vector<StableId>{source,office}&&e->receipt_ids==e->fact_ids;}
// 同候选实际result分配并发布到原cache/history；待测binder不能收一个内容相同的临时复制对象。
std::shared_ptr<const CommitResult> commit(Fixture& f,const PoliticalDismissalSource& s){auto r=std::make_shared<CommitResult>();r->ok=true;r->kind="political_dismiss";r->tick=f.common.tick();r->revision=++f.common.state().identity.revision;r->result_id=take(f.common.next_id("result"));auto d=std::make_shared<ReceiptDetails>();PoliticsEffects e;e.fact_ids=e.receipt_ids={s.dismissal_fact_id,s.office_change_fact_id};d->data=e;r->details=d;f.common.state().request_sequences.set("leader",1);f.common.state().results.insert("leader:1",r);f.common.state().history.push_back({r->tick,r->kind,"leader",r->result_id,{}});return r;}
}
int main(){try{Fixture f;auto s=f.remove();PoliticalDismissalSourceState before,state;state.dismissals.insert(s.dismissal_fact_id,{s,{}});check(take(political_dismissal_new_result_source(before,state,"leader","political_dismiss",0))==s.dismissal_fact_id,"only actual candidate's new source selected");check(!political_dismissal_new_result_source(before,state,"worker","political_dismiss",0).ok,"other actor cannot claim source");check(!political_dismissal_new_result_source(before,state,"leader","wait",0).ok,"other command cannot introduce source");auto r=commit(f,s);auto copy=*r;check(!bind_political_dismissal_result(f.common,state,s.dismissal_fact_id,"leader",1,copy,exact).ok,"copied result is not original cached result object");check(bind_political_dismissal_result(f.common,state,s.dismissal_fact_id,"leader",1,*r,exact).ok,"true original cache and last history permit permanent binding");check(validate_political_dismissal_results(f.common,state,exact).ok,"fresh source and original result cross-check");
 auto json=encode_political_dismissal_sources(state);auto cold=take(decode_political_dismissal_sources(json));check(compare_boundary(json,encode_political_dismissal_sources(cold)).exact(),"nonempty source sidecar JSON exact roundtrip");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);take(visit_political_dismissal_sources(writer,cold));take(writer.finish());PoliticalDismissalSourceState decoded;const auto& input=bytes;CodecVisitor reader(input);take(visit_political_dismissal_sources(reader,decoded));take(reader.finish());check(compare_boundary(json,encode_political_dismissal_sources(decoded)).exact(),"nonempty sidecar typed roundtrip");auto extra=json;std::get<BoundaryValue::Dict>(extra.data).emplace_back("another_office",BoundaryValue{"forged"});check(!decode_political_dismissal_sources(extra).ok,"unknown field cannot add a second Office source");auto invalid=state;invalid.version=2;check(!decode_political_dismissal_sources(encode_political_dismissal_sources(invalid)).ok,"unknown sidecar version rejected");
 auto old=state;state.dismissals.find(s.dismissal_fact_id)->source.authority.authority_epoch=1;check(!political_dismissal_new_result_source(old,state,"leader","wait",0).ok,"old authority cannot change in unrelated submission");state=old;f.common.state().results={};f.common.state().history.clear();check(validate_political_dismissal_results(f.common,state,exact).ok,"all cached results trimmed preserves permanent source");state.dismissals.find(s.dismissal_fact_id)->actual_result.reset();check(!validate_political_dismissal_results(f.common,state,exact).ok,"trimmed cache cannot excuse missing permanent result");state=old;state.dismissals.find(s.dismissal_fact_id)->actual_result->result_id=s.office_change_fact_id;check(!validate_political_dismissal_results(f.common,state,exact).ok,"actual Office fact cannot masquerade as result");state=old;state.dismissals.find(s.dismissal_fact_id)->actual_result->result_id="result:"+s.office_change_fact_id.substr(s.office_change_fact_id.find(':')+1);check(!validate_political_dismissal_results(f.common,state,exact).ok,"result number cannot collide with any real fact");
 f.common.state().results.insert("leader:1",r);f.common.state().history.push_back({r->tick,r->kind,"leader",r->result_id,{}});PoliticalDismissalSourceState empty;check(!validate_political_dismissal_results(f.common,empty,exact).ok,"orphan retained dismissal result cannot hide behind empty sidecar");std::cout<<checks<<" dismissal sidecar/result checks; no World\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
